"""PHASE 2 SUPPLEMENT — ad-campaign break-even / scale decision tool.

Turns the Phase 2 conversion lift into a money decision. The lift itself is
measured; the money inputs are CLIENT ASSUMPTIONS, clearly labelled, because the
A/B dataset has no revenue or spend per user.

Inputs (assumptions):
  --value-per-conversion   gross margin (or revenue) generated by one conversion
  --ad-cost-per-user       fully-loaded ad cost of exposing ONE user
  --users                  cohort size for the arithmetic (default 100,000)

Output: net value per cohort with a scale / hold / cut verdict, plus the
break-even value-per-conversion and a sensitivity grid.

Run:  ./venv/Scripts/python.exe scripts/breakeven.py
      ./venv/Scripts/python.exe scripts/breakeven.py --value-per-conversion 45 --ad-cost-per-user 0.08
"""
import argparse
from pathlib import Path
import numpy as np
import pandas as pd

OUT = Path("deliverables/outputs")
OUT.mkdir(parents=True, exist_ok=True)
pd.set_option("display.width", 200)

ap = argparse.ArgumentParser()
ap.add_argument("--value-per-conversion", type=float, default=30.0,
                help="ASSUMPTION: gross value of one conversion (default 30.0)")
ap.add_argument("--ad-cost-per-user", type=float, default=0.05,
                help="ASSUMPTION: ad cost per exposed user (default 0.05)")
ap.add_argument("--users", type=int, default=100_000, help="cohort size (default 100000)")
ap.add_argument("--currency", default="EUR", help="label only")
args = ap.parse_args()

# ── measured input: the Phase 2 lift (read, not hardcoded) ───────────────
lift = pd.read_csv(OUT / "ab_lift_ci.csv").set_index("metric")["value"]
abs_pp, lo_pp, hi_pp = lift["absolute_lift_pp"], lift["ci95_diff_pp_lo"], lift["ci95_diff_pp_hi"]
# 1 percentage point = 1 conversion per 100 users = 1,000 per 100,000 users
per_cohort = {k: pp * args.users / 100 for k, pp in
              [("low", lo_pp), ("expected", abs_pp), ("high", hi_pp)]}

cost = args.ad_cost_per_user * args.users

def verdict(net_lo, net_exp):
    if net_lo > 0:
        return "SCALE"
    if net_exp > 0:
        return "HOLD (uncertain)"
    return "CUT"

rows = []
for name, inc in per_cohort.items():
    value = inc * args.value_per_conversion
    net = value - cost
    rows.append({
        "scenario": name,
        "lift_pp": {"low": lo_pp, "expected": abs_pp, "high": hi_pp}[name],
        "incremental_conversions": inc,
        "value_created": value,
        "ad_cost": cost,
        "net_value": net,
        "roi": value / cost if cost else np.nan,
    })
scen = pd.DataFrame(rows)
net_lo = scen.loc[scen.scenario == "low", "net_value"].iloc[0]
net_exp = scen.loc[scen.scenario == "expected", "net_value"].iloc[0]

be_value = cost / per_cohort["expected"] if per_cohort["expected"] else np.nan
be_cost = (per_cohort["expected"] * args.value_per_conversion) / args.users

print("=" * 78)
print("AD-CAMPAIGN BREAK-EVEN / SCALE DECISION")
print("=" * 78)
print(f"Measured lift (Phase 2, n=588,101 users): "
      f"{abs_pp:+.3f}pp  (95% CI {lo_pp:+.3f} to {hi_pp:+.3f} pp)")
print(f"ASSUMPTIONS (client-supplied, not from data):")
print(f"  value per conversion : {args.currency} {args.value_per_conversion:,.2f}")
print(f"  ad cost per user     : {args.currency} {args.ad_cost_per_user:,.4f}")
print(f"  cohort size          : {args.users:,} users")
print("-" * 78)
print(scen.round(2).to_string(index=False))
print("-" * 78)
print(f"Break-even value per conversion : {args.currency} {be_value:,.2f}")
print(f"  -> if one conversion is worth MORE than this, scaling pays off")
print(f"Break-even ad cost per user     : {args.currency} {be_cost:,.4f}")
print(f"\nVERDICT: {verdict(net_lo, net_exp)}  "
      f"(worst-case net {args.currency} {net_lo:,.0f}; expected net {args.currency} {net_exp:,.0f})")

# sensitivity grid: net value per cohort, with verdict per cell
vals = [10, 20, 30, 50, 100]
costs = [0.02, 0.05, 0.10, 0.20]
grid = pd.DataFrame(index=[f"value={v}" for v in vals],
                    columns=[f"cost={c}" for c in costs], dtype=object)
for v in vals:
    for c in costs:
        inc = per_cohort["expected"]
        n_lo = inc * v - c * args.users
        n_ex = inc * v - c * args.users
        grid.loc[f"value={v}", f"cost={c}"] = f"{n_lo:,.0f} {verdict(n_lo, n_ex)}"
print("\nSensitivity (expected lift; net value per cohort + verdict):")
print(grid.to_string())

scen.to_csv(OUT / "breakeven_scenarios.csv", index=False)
grid.to_csv(OUT / "breakeven_sensitivity.csv")
print(f"\nAssumption sensitivity of the break-even value: "
      f"at cost {args.currency} {args.ad_cost_per_user:.3f}, break-even value per "
      f"conversion = {args.currency} {be_value:.2f}.")
